<?php require dirname(__DIR__).'/layouts/admin_start.php';$h=fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');$restricted=(\BloodHub\Services\ClientScopeService::resolve()['restricted']);?>
<section class="report-kpis"><?php foreach(['PENDING_RELEASE'=>'Aguardando liberação','RELEASED'=>'Liberados no período','REVISED'=>'Retificados','CANCELLED'=>'Cancelados']as$k=>$label):if($restricted&&in_array($k,['PENDING_RELEASE','CANCELLED'],true))continue;?><article><span><?=$h($label)?></span><strong><?=$kpis[$k]?></strong></article><?php endforeach?></section>
<section class="content-card report-filters"><form method="get" action="/reports"><label>Período de<input type="date" name="from" value="<?=$h($_GET['from']??'')?>"></label><label>Até<input type="date" name="to" value="<?=$h($_GET['to']??'')?>"></label><?php if(!$restricted):?><label>Tipo de cliente<select name="client_type"><option value="all">Todos</option><option value="internal" <?=($_GET['client_type']??'')==='internal'?'selected':''?>>Interno</option><option value="external" <?=($_GET['client_type']??'')==='external'?'selected':''?>>Externo</option></select></label><label>Cliente<select name="client_id"><option value="">Todos</option><?php foreach($catalogs['clients']as$c):?><option value="<?=$c['id']?>" <?=($_GET['client_id']??'')==$c['id']?'selected':''?>><?=$h($c['name'])?></option><?php endforeach?></select></label><?php endif?><label>Unidade<select name="unit_id"><option value="">Todas</option><?php foreach($catalogs['units']as$u):?><option value="<?=$u['id']?>" <?=($_GET['unit_id']??'')==$u['id']?'selected':''?>><?=$h($u['name'])?></option><?php endforeach?></select></label><label>Hemocomponente<select name="component_id"><option value="">Todos</option><?php foreach($catalogs['components']as$c):?><option value="<?=$c['id']?>" <?=($_GET['component_id']??'')==$c['id']?'selected':''?>><?=$h($c['code'].' - '.$c['name'])?></option><?php endforeach?></select></label><label>Nº da doação<input name="donation" value="<?=$h($_GET['donation']??'')?>"></label><label>Código LCQH<input name="lcqh" value="<?=$h($_GET['lcqh']??'')?>"></label><?php if(!$restricted):?><label>Status<select name="status"><option value="">Todos</option><?php foreach($labels as$k=>$v):?><option value="<?=$k?>" <?=($_GET['status']??'')===$k?'selected':''?>><?=$h($v)?></option><?php endforeach?></select></label><?php endif?><div class="filter-actions"><button class="button">Filtrar</button><a class="button button-secondary" href="/reports">Limpar</a></div></form></section>
<section class="content-card"><div class="table-wrap"><table class="reports-table"><thead><tr><th>Recebimento</th><th>Cliente</th><th>Unidade</th><th>Hemocomponente</th><th>Doação</th><th>Código LCQH</th><th>Status</th><th>Emissão</th><th>Ações</th></tr></thead><tbody><?php foreach($rows as$r):?><tr><td><?=$r['received_at']?date('d/m/Y',strtotime($r['received_at'])):'—'?></td><td><?=$h($r['client_name'])?></td><td><?=$h($r['unit_name']?:'—')?></td><td><?=$h($r['component_code'])?></td><td><?=$h($r['donation_number']?:'—')?></td><td><?=$h($r['lcqh_code']?:'—')?></td><td><span class="report-status status-<?=strtolower($r['status'])?>"><?=$h($labels[$r['status']])?></span><?php if($r['needs_revision']):?><small class="revision-alert">Resultado posteriormente retificado</small><?php endif?></td><td><?=$r['released_at']?date('d/m/Y H:i',strtotime($r['released_at'])):'—'?></td><td><div class="report-actions"><?php if(!$r['report_id']):?><a class="button button-secondary button-compact" href="/reports/preview?sample_id=<?=$r['sample_id']?>">Prévia</a><?php if($canManage):?><button class="button button-compact" data-release='<?=$h(json_encode($r,JSON_UNESCAPED_UNICODE))?>'>Liberar</button><?php endif?><?php else:?><a class="button button-secondary button-compact" href="/reports/view?id=<?=$r['report_id']?>">Visualizar</a><?php if($r['status']!=='CANCELLED'):?><a class="button button-compact" href="/reports/download?id=<?=$r['report_id']?>">Baixar PDF</a><?php endif?><?php if($r['needs_revision']&&$canRevise):?><button class="button button-compact" data-revise="<?=$r['report_id']?>">Retificar</button><?php endif?><?php if($r['status']!=='CANCELLED'&&$canCancel):?><button class="button button-danger button-compact" data-cancel="<?=$r['report_id']?>">Cancelar</button><?php endif?><?php endif?></div></td></tr><?php endforeach?><?php if(!$rows):?><tr><td colspan="9" class="empty-state">Nenhum laudo encontrado para os filtros informados.</td></tr><?php endif?></tbody></table></div></section>
<dialog id="release-modal" class="report-dialog"><form method="post" action="/reports/release"><input type="hidden" name="_csrf" value="<?=$h($csrf)?>"><input type="hidden" name="sample_id"><header><h2>Liberar laudo</h2><p>Revise os dados antes de confirmar a liberação eletrônica.</p></header><div class="release-summary" data-summary></div><label>Observação<textarea name="notes" rows="3"></textarea></label><section class="release-responsible"><small>Responsável pela liberação</small><strong><?=$h($releaseUser['professional_name']??'Não informado')?></strong><span><?=$h(trim(($releaseUser['professional_council']??'').' '.($releaseUser['professional_registration']??''))?:'Dados profissionais incompletos')?></span></section><div class="dialog-actions"><button type="button" class="button button-secondary" data-close>Cancelar</button><button class="button">Liberar laudo</button></div></form></dialog>
<dialog id="revise-modal" class="report-dialog"><form method="post" action="/reports/revise"><input type="hidden" name="_csrf" value="<?=$h($csrf)?>"><input type="hidden" name="report_id"><h2>Gerar nova versão</h2><label>Motivo da retificação *<textarea name="reason" required></textarea></label><label>Observações do novo laudo<textarea name="notes"></textarea></label><div class="dialog-actions"><button type="button" class="button button-secondary" data-close>Cancelar</button><button class="button">Gerar versão retificada</button></div></form></dialog>
<dialog id="cancel-modal" class="report-dialog"><form method="post" action="/reports/cancel"><input type="hidden" name="_csrf" value="<?=$h($csrf)?>"><input type="hidden" name="report_id"><h2>Cancelar laudo</h2><label>Motivo do cancelamento *<textarea name="reason" required></textarea></label><div class="dialog-actions"><button type="button" class="button button-secondary" data-close>Voltar</button><button class="button button-danger">Cancelar laudo</button></div></form></dialog>
